inline const std::array<uint8_t, kSpeciesCount * kBytesPerSpecies>& table(SourceGame game) noexcept {
    switch (game) {
        case SourceGame::RubyGBA:
        case SourceGame::SapphireGBA: return kRubySapphire;
        case SourceGame::EmeraldGBA: return kEmerald;
        case SourceGame::FireRedGBA:
        case SourceGame::LeafGreenGBA: return kFireRedLeafGreen;
    }
    return kRubySapphire;
}

inline bool test(const std::array<uint8_t, kSpeciesCount * kBytesPerSpecies>& bits,
                 uint16_t species, uint16_t move) noexcept {
    if (species == 0 || species >= kSpeciesCount || move == 0 || move >= kMoveCount)
        return false;
    const std::size_t offset = static_cast<std::size_t>(species) * kBytesPerSpecies + (move >> 3);
    return (bits[offset] & static_cast<uint8_t>(1u << (move & 7))) != 0;
}

inline bool directlyLearnable(SourceGame game, uint16_t species, uint16_t move) noexcept {
    return test(table(game), species, move);
}

inline bool learnableSomewhere(uint16_t species, uint16_t move) noexcept {
    return test(kRubySapphire, species, move) ||
           test(kEmerald, species, move) ||
           test(kFireRedLeafGreen, species, move);
}

inline Availability classify(SourceGame game, uint16_t species, uint16_t move,
                             const std::array<uint16_t, 4>& sourceMoves) noexcept {
    if (move == 0) return Availability::Direct;
    if (move >= kMoveCount || species == 0 || species >= kSpeciesCount)
        return Availability::Invalid;
    if (directlyLearnable(game, species, move)) return Availability::Direct;
    if (learnableSomewhere(species, move)) return Availability::Transfer;
    for (uint16_t source : sourceMoves)
        if (source == move) return Availability::Preserved;
    return Availability::Invalid;
}

inline std::vector<uint16_t> selectableMoves(SourceGame game, uint16_t species,
                                             const std::array<uint16_t, 4>& sourceMoves) {
    std::vector<uint16_t> out;
    out.reserve(128);
    out.push_back(0);
    for (uint16_t move = 1; move < kMoveCount; ++move) {
        const auto status = classify(game, species, move, sourceMoves);
        if (status != Availability::Invalid) out.push_back(move);
    }
    return out;
}

